/**
 * Infrastructure accessors for the standalone subscription-consumer handlers
 * in this directory.
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 *
 * A consumer handler module is a bare exported function, imported directly by
 * a serverless adapter (an AWS consumer-Lambda entry point, an Azure Functions
 * v4 registration). Neither adapter has a NestJS injector, so a handler body
 * that touches an entity, emits a domain event, or reads a NoSQL collection
 * cannot receive those through constructor injection the way an in-process
 * consumer class does. It resolves them here instead.
 *
 * The module below is a purpose-built root, exactly like the enqueue worker's
 * own standalone module: it boots in its own application context rather than
 * nested inside AppModule, so it registers everything these handlers need
 * instead of relying on AppModule's registrations.
 *
 * The context is created once per process and reused. On a warm serverless
 * container every later invocation reuses the same context -- and therefore
 * the same connection pool -- rather than paying to build one per event. The
 * EntityManager is forked per call because MikroORM's root manager carries a
 * shared identity map that must not be reused across concurrent invocations.
 */
import type { INestApplicationContext } from '@nestjs/common';
import { Injectable, Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { EntityManager } from '@mikro-orm/core';
import { OrderDbDatabaseModule } from '../order-db/database.module';

/**
 * Holds one EntityManager per database these handlers reach.
 *
 * A service owning several rdbms blocks registers each under its own MikroORM
 * contextName and has no default context, so each of those is addressed by the
 * same `@InjectEntityManager('<context>')` binding the in-process consumer
 * classes use. A service owning a single block registers it unnamed, and its
 * manager resolves by type with no decorator -- `@InjectEntityManager()` takes
 * a context name and is not a valid no-argument call.
 */
@Injectable()
class ConsumerEntityManagers {
  constructor(
    readonly em: EntityManager,
  ) {}
}

@Module({
  imports: [
    OrderDbDatabaseModule,
  ],
  providers: [ConsumerEntityManagers],
})
class SubscriptionConsumerRuntimeModule {}

let contextPromise: Promise<INestApplicationContext> | undefined;

/**
 * The process-wide application context, created on first use.
 *
 * The promise itself is memoized, not its resolved value, so two concurrent
 * first invocations await one bootstrap instead of racing to build two.
 */
function runtimeContext(): Promise<INestApplicationContext> {
  contextPromise ??= NestFactory.createApplicationContext(
    SubscriptionConsumerRuntimeModule,
    { logger: false },
  );
  return contextPromise;
}

/**
 * A forked EntityManager scoped to one handler invocation, for the
 * default database.
 */
export async function consumerEntityManager(): Promise<EntityManager> {
  const context = await runtimeContext();
  return context.get(ConsumerEntityManagers).em.fork();
}
